#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>
#include <vector>

class Queue {
public:
    void push(int value) {
        std::scoped_lock lock(mutex_);
        items_.push(value);
    }

    // Check and pop under one lock: the whole operation, or none of it.
    std::optional<int> try_pop() {
        std::scoped_lock lock(mutex_);
        if (items_.empty()) return std::nullopt;
        int value = items_.front();
        items_.pop();
        return value;
    }

    // Honest answers, immediately stale in a multi-threaded caller.
    // Useful for diagnostics; never for deciding whether to pop.
    bool empty() const {
        std::scoped_lock lock(mutex_);
        return items_.empty();
    }

    std::size_t size() const {
        std::scoped_lock lock(mutex_);
        return items_.size();
    }

private:
    mutable std::mutex mutex_;
    std::queue<int> items_;
};
